export function latLonToZurichWorld(
  lat: number,
  lon: number
): [number, number] {
  const rawKmX = (lon - ZURICH_GEO_CONFIG.centerLon) * (ZURICH_GEO_CONFIG.kmPerDegLon ?? 90);
  const rawKmZ = -(lat - ZURICH_GEO_CONFIG.centerLat) * (ZURICH_GEO_CONFIG.kmPerDegLat ?? 111.1);
  const distKm = Math.hypot(rawKmX, rawKmZ);
  const coreRadiusKm = ZURICH_GEO_CONFIG.coreRadiusKm ?? 7.5;
  const worldUnitsPerKm = ZURICH_GEO_CONFIG.worldUnitsPerKm ?? 10.8;
  let effectiveKm = distKm;
  if (distKm > coreRadiusKm) {
    effectiveKm = coreRadiusKm + Math.log1p((distKm - coreRadiusKm) * 0.30) * 5.6;
  }
  const scale = distKm > 0.0001 ? (effectiveKm / distKm) * worldUnitsPerKm : worldUnitsPerKm;
  return [Math.round(rawKmX * scale * 100) / 100, Math.round(rawKmZ * scale * 100) / 100];
}

